// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address nonOwner;

    function setUp() public { 
        c = new C(address(this), address(this)); 
        nonOwner = address(0xABCD);
    }

    function testFuzz_property(address randomCaller) public {
        vm.assume(randomCaller != address(this)); // Not the owner
        vm.assume(randomCaller != address(0)); // Zero address not relevant

        // Record the initial rewardDistributor
        address initialDistributor = c.rewardDistributor();

        // Perform an addReward call as a non-owner (should revert in reference)
        vm.prank(randomCaller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.addReward.selector, address(0x1)));

        // The rule: if the caller is not the owner, the call must revert (for reference).
        // In the mutant, the call succeeds but should not change rewardDistributor.
        // We check: after the call, rewardDistributor is unchanged.
        assertTrue(!success || c.rewardDistributor() == initialDistributor);
    }
}

