// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address user, address rewardToken, uint256 stakeAmount, uint256 rewardAmount) public {
        vm.assume(user != address(0) && rewardToken != address(0));
        vm.assume(stakeAmount > 0 && stakeAmount <= 1e30);
        vm.assume(rewardAmount > 0 && rewardAmount <= 1e30);

        // Set up reward token
        c.addReward(rewardToken);

        // Fund this contract with staking tokens and reward tokens
        // We'll use this contract as the staking token holder and reward distributor
        // For simplicity, we use address(this) as the staking token source
        deal(address(c.stakingToken()), address(this), stakeAmount);
        deal(rewardToken, address(this), rewardAmount);

        // Approve staking tokens
        IERC20(address(c.stakingToken())).approve(address(c), stakeAmount);

        // User stakes
        vm.prank(user);
        // Need to give user tokens first
        deal(address(c.stakingToken()), user, stakeAmount);
        vm.startPrank(user);
        IERC20(address(c.stakingToken())).approve(address(c), stakeAmount);
        c.stake(stakeAmount);
        vm.stopPrank();

        // Distribute reward
        IERC20(rewardToken).approve(address(c), rewardAmount);
        c.notifyRewardAmount(rewardToken, rewardAmount);

        // Warp to after period
        vm.warp(block.timestamp + 7 days + 1);

        // User claims reward
        vm.prank(user);
        c.getReward(user);

        // After claiming, claimableRewards should be zero for this user and token
        assertTrue(c.claimableRewards(user, rewardToken) == 0);
    }
}

