pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address staker, address rewardToken, uint256 stakeAmount) public {
        vm.assume(staker != address(0));
        vm.assume(rewardToken != address(0));
        vm.assume(stakeAmount > 0 && stakeAmount <= 1e30);

        // Fund staker and approve
        deal(address(c.stakingToken()), staker, stakeAmount);
        vm.prank(staker);
        IERC20(address(c.stakingToken())).approve(address(c), stakeAmount);

        // Staker stakes
        vm.prank(staker);
        c.stake(stakeAmount);

        // Add reward token
        c.addReward(rewardToken);

        // Now call getReward with staker and rewardToken
        uint256 balanceBefore = IERC20(rewardToken).balanceOf(address(staker));
        vm.prank(address(this));
        try c.getReward(staker, rewardToken) {
            uint256 balanceAfter = IERC20(rewardToken).balanceOf(address(staker));
            assertTrue(balanceAfter == balanceBefore, "getReward should not have transferred tokens");
        } catch {
            assertTrue(true, "getReward reverted");
        }
    }
}

