        c.addReward(rewardToken);
        deal(rewardToken, address(this), 1e20);
        c.notifyRewardAmount(rewardToken, 1e20);

        // Record claimable before getRewards call
        uint256 claimableBefore = c.claimableRewards(user, rewardToken);

